def _im(n):
    try:
        __import__(n); return True
    except ImportError:
        return False

_BASE = ["requests", "colorama", "rich", "aiohttp", "httpx"]
_missing = [m for m in _BASE if not _im(m)]
if _missing:
    _ni = os.environ.get("CCT_NO_INSTALL") == "1"
    try:
        from rich.console import Console
        from rich.panel import Panel
        Console().print(Panel.fit(f"[red]Missing:[/red] {', '.join(_missing)}\n\nInstall now?", title="Setup", border_style="cyan"))
    except ImportError:
        print(f"[!] Missing: {', '.join(_missing)}")
    if _ni:
        print(f"Run: pip install {' '.join(_missing)}"); sys.exit(1)
