def _derive(pw, salt_hex):
    return hashlib.pbkdf2_hmac("sha256", pw.encode(), bytes.fromhex(salt_hex), 200000)

def _init_pass():
    global _PASS_HASH
    if not _PASS_HASH:
        _PASS_HASH = _derive("cct1234", _PASS_SALT).hex()

def _validate_identity():
    try:
        if _x1 == 0 and _x2 == 0 and _x3 == 0 and _x4 == 0:
            return DEV == "NASIF HIMADRI" and OWNER == "ANIK" and TOOL == "CCT_DDOS"
        h = hashlib.sha256(f"{DEV}|{OWNER}|{TOOL}".encode()).digest()
        hi = int.from_bytes(h[:8], "big") ^ _x1
        lo = int.from_bytes(h[8:16], "big") ^ _x2
        mid = int.from_bytes(h[16:24], "big") ^ _x3
        tail = int.from_bytes(h[24:], "big") ^ _x4
        if hi != 0x1e2f3a4b5c6d7e8f: return False
        if lo != 0x9a8b7c6d5e4f3021: return False
        if mid != 0x0d1c2b3a4958677: return False
        if tail != 0x6f7e8d9c0b1a2e: return False
        if DEV != "NASIF HIMADRI": return False
        if OWNER != "ANIK": return False
        if TOOL != "CCT_DDOS": return False
        return True
    except Exception:
        return False

