def _slowprint(text, color=CL.CYAN, delay=0.008):
    for ch in text:
        sys.stdout.write(f"{color}{ch}{CL.RESET}"); sys.stdout.flush(); time.sleep(delay)
    sys.stdout.write("\n")


def _safe_clear():
    try:
        os.system("cls" if os.name == "nt" else "clear")
    except Exception:
        pass


def _center_block(text, width=None):
    """Center a multi-line block as a whole, not line-by-line,
    so the art's internal alignment is preserved."""
    if width is None:
        try:
            width = shutil.get_terminal_size((80, 24)).columns
        except Exception:
            width = 80

    lines = text.strip("\n").split("\n")
    max_len = max((len(line) for line in lines), default=0)
    pad = max((width - max_len) // 2, 0)

    return "\n".join((" " * pad) + line for line in lines)


