class AF:
    _tbl = {}
    @classmethod
    def reg(cls, name, aliases, desc, cat, fn):
        for n in [name] + aliases: cls._tbl[n.lower()] = (desc, cat, fn)
    @classmethod
    def get(cls, name): return cls._tbl.get(name.lower())
    @classmethod
    def table(cls): return dict(cls._tbl)
    @classmethod
    def unique_count(cls): return len(set(id(fn) for _,_,fn in cls._tbl.values()))

