class AUTH:
    def __init__(self):
        _init_pass()
        self._att = 0; self._lock_until = 0.0; self._lk = threading.Lock()
    def _read_password(self):
        try:
            if sys.stdin is not None and sys.stdin.isatty():
                p = getpass.getpass("[?] Password: ")
                if p: return p
        except Exception: pass
        try: return input("[?] Password: ")
        except EOFError: return ""
    def login(self):
        with self._lk:
            if time.time() < self._lock_until:
                print(f"{CL.RED}[!] Locked for {int(self._lock_until-time.time())}s.{CL.RESET}"); return False
        _banner_login()
        _cn.print(Panel.fit(
            f"[bold cyan]{TOOL} LOGIN[/bold cyan]\n"
            f"[green]Developer: {DEV}[/green]\n"
            f"[magenta]Owner: {OWNER}[/magenta]\n"
            f"[dim]Enter credentials to continue[/dim]",
            border_style="bright_magenta", padding=(0, 2), box=HEAVY_EDGE,
        ))
        u = input("[?] Username: ").strip()
        p = self._read_password()
        p = p.replace("\r", "").replace("\n", "").replace("\x00", "").strip()
        u_clean = u.replace("\r", "").replace("\n", "").replace("\x00", "").strip()
        u_ok = hmac.compare_digest(u_clean.encode(), _USER.encode())
        h_ok = hmac.compare_digest(_derive(p, _PASS_SALT), bytes.fromhex(_PASS_HASH))
        if u_ok and h_ok:
            print(f"{CL.GREEN}[+] Login OK.{CL.RESET}"); time.sleep(0.4); return True
        with self._lk:
            self._att += 1
            if self._att >= MAX_AT:
                self._lock_until = time.time() + LOCK_SEC; self._att = 0
                print(f"{CL.RED}[!] Locked for {LOCK_SEC}s.{CL.RESET}")
            else: print(f"{CL.RED}[!] Invalid. {MAX_AT-self._att} left.{CL.RESET}")
        return False

